import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    queries = []
    for i in range(t):
        queries.append(int(input_data[i + 1]))

    results = []
    for x in queries:
        if x == 7:
            results.append("YES")
        elif x >= 8:
            remainder = x - 7
            if remainder % 4 == 0:
                results.append("YES")
            else:
                results.append("NO")
        else:
            results.append("NO")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
